import type { Status, StatusItem } from '../../types';
import './StatusList.css';

export const STATUS_LABELS: Record<Status, string> = {
  todo: 'To Do',
  'in-progress': 'In Progress',
  done: 'Done',
  blocked: 'Blocked',
};

export const SKELETON_COUNT = 6;

const STATUS_ORDER: Status[] = ['todo', 'in-progress', 'done', 'blocked'];

export function statusColor(status: Status): string {
  switch (status) {
    case 'todo': return 'status-todo';
    case 'in-progress': return 'status-in-progress';
    case 'done': return 'status-done';
    case 'blocked': return 'status-blocked';
  }
}

interface StatusListProps {
  items: StatusItem[] | null;
}

// null = loading; array = loaded
export function StatusList({ items }: StatusListProps): JSX.Element {
  if (items === null) {
    return (
      <ul role="list" className="status-list">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="skeleton-item">
            <span className="skeleton-bar" />
          </li>
        ))}
      </ul>
    );
  }

  const grouped: Record<Status, StatusItem[]> = {
    todo: [],
    'in-progress': [],
    done: [],
    blocked: [],
  };

  for (const item of items) {
    grouped[item.status].push(item);
  }

  return (
    <div className="status-list">
      {STATUS_ORDER.map((status) => {
        const group = grouped[status];
        if (group.length === 0) return null;
        return (
          <section key={status} className="status-group">
            <h2 className="group-heading">{STATUS_LABELS[status]}</h2>
            <ul role="list" className="item-list">
              {group.map((item) => (
                <li
                  key={item.id}
                  className={`status-item ${statusColor(item.status)}`}
                >
                  {item.title}
                </li>
              ))}
            </ul>
          </section>
        );
      })}
    </div>
  );
}

