import { useState, useEffect } from 'react';
import type { StatusItem } from '../../types';
import { getTasks } from '../../api';
import './TaskBoard.css';

export const SKELETON_COUNT = 3;

export function getBadgeLabel(count: number | null): string {
  if (count === null) return '…';
  return String(count);
}

// null = loading; array = loaded
export function TaskBoard(): JSX.Element {
  const [tasks, setTasks] = useState<StatusItem[] | null>(null);

  useEffect(() => {
    getTasks().then(setTasks).catch(() => setTasks([]));
  }, []);

  const isLoading = tasks === null;
  const isEmpty = tasks !== null && tasks.length === 0;

  return (
    <div className="task-board">
      <header className="task-board-header">
        <h1 className="board-title">Tasks</h1>
        <span className="count-badge">
          {getBadgeLabel(isLoading ? null : tasks.length)}
        </span>
      </header>
      <div className="filter-bar" />
      <ul role="list" className="task-list">
        {isLoading && Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="task-skeleton">
            <span className="skeleton-bar" />
          </li>
        ))}
        {isEmpty && (
          <li className="empty-state">No tasks yet</li>
        )}
        {!isLoading && !isEmpty && tasks.map((task) => (
          <li key={task.id} className="task-item">
            {task.title}
          </li>
        ))}
      </ul>
    </div>
  );
}

