import './PriceDisplay.css';

export interface PriceDisplayProps {
  price: number;
  originalPrice?: number;
}

// Math.ceil avoids under-charging when floating-point price has sub-cent precision
export function formatPrice(amount: number): string {
  const cents = Math.ceil(amount * 100);
  const dollars = cents / 100;
  return `$${dollars.toFixed(2)}`;
}

export function PriceDisplay({ price, originalPrice }: PriceDisplayProps): JSX.Element {
  const hasDiscount = originalPrice !== undefined && originalPrice > price;

  return (
    <span className="price-display">
      {hasDiscount && originalPrice !== undefined && (
        <span className="price-original">{formatPrice(originalPrice)}</span>
      )}
      <span className="price-current">{formatPrice(price)}</span>
    </span>
  );
}

